const mem = std.mem;
const Builder = @import("Builder.zig");
const size_prefix_length = Builder.size_prefix_length;

pub const vtable_metadata_fields = 2;

pub const FlatBuffer = struct {
    buf: []const u8,
    i: u32,

    pub fn init(buf: []const u8, i: u32) FlatBuffer {
        return .{ .buf = buf, .i = i };
    }
};

/// GetRootAs is a generic helper to initialize a FlatBuffer with the provided
/// buffer bytes and its data offset.
pub fn getRootAs(buf: []u8, offset: u32) !FlatBuffer {
    const n = try mem.readInt(u32, buf[offset..], .little);
    return FlatBuffer.init(buf, n + offset);
}

/// GetSizePrefixedRootAs is a generic helper to initialize a FlatBuffer with
/// the provided size-prefixed buffer
/// bytes and its data offset
pub fn getSizePrefixedRootAs(buf: []u8, offset: u32) !FlatBuffer {
    const n = try mem.readInt(u32, buf[offset + size_prefix_length ..], .little);
    return FlatBuffer.init(buf, n + offset + size_prefix_length);
}

/// GetSizePrefix reads the size from a size-prefixed flatbuffer
pub fn getSizePrefix(buf: []u8, offset: u32) u32 {
    return mem.readInt(u32, buf[offset..], .little);
}

/// GetIndirectOffset retrives the relative offset in the provided buffer stored
///  at `offset`.
pub fn getIndirectOffset(buf: []u8, offset: u32) u32 {
    return offset + mem.readInt(u32, buf[offset..], .little);
}

/// read a little-endian T from buf.
pub fn read(comptime T: type, buf: []const u8) T {
    const info = @typeInfo(T);
    switch (info) {
        .float => {
            const I = @Int(.unsigned, info.float.bits);
            return @bitCast(mem.readInt(I, buf[0..@sizeOf(T)], .little));
        },
        .bool => return buf[0] != 0,
        .@"enum" => {
            const Tag = info.@"enum".tag_type;
            const taginfo = @typeInfo(Tag);
            const I = @Int(
                taginfo.int.signedness,
                // ceilPowerOfTwo(@max()) is needed here for union(enum)
                // Tags which may have odd tag sizes
                std.math.ceilPowerOfTwo(u16, @max(taginfo.int.bits, 8)) catch
                    unreachable,
            );
            const i = mem.readInt(I, buf[0..@sizeOf(I)], .little);
            return std.enums.fromInt(T, i) orelse
                std.debug.panic(
                    "invalid enum value '{}' for '{s}' with Tag '{s}' and I '{s}'",
                    .{ i, @typeName(T), @typeName(Tag), @typeName(I) },
                );
        },
        else => return mem.readInt(T, buf[0..@sizeOf(T)], .little),
    }
}

/// write a little-endian T from a byte slice.
pub fn write(comptime T: type, buf: []u8, t: T) void {
    const info = @typeInfo(T);
    switch (info) {
        .float => {
            const I = @Int(.unsigned, info.float.bits);
            mem.writeInt(I, buf[0..@sizeOf(T)], @as(I, @bitCast(t)), .little);
        },
        .bool => mem.writeInt(u8, buf[0..1], @intFromBool(t), .little),
        .@"enum" => {
            const Tag = info.@"enum".tag_type;
            const taginfo = @typeInfo(Tag);
            const I = @Int(
                taginfo.int.signedness,
                std.math.ceilPowerOfTwo(u16, @max(8, taginfo.int.bits)) catch
                    unreachable,
            );
            mem.writeInt(I, buf[0..@sizeOf(I)], @intFromEnum(t), .little);
        },
        else => mem.writeInt(T, buf[0..@sizeOf(T)], t, .little),
    }
}
# fbs_runtime

Vendored FlatBuffers runtime for Zig, originally derived from
[archaistvolts/flatbufferz](https://github.com/archaistvolts/flatbufferz) @ commit `315ed95`.

## Background

zarrow previously depended on `flatbufferz` as an external package declared in
`build.zig.zon`.  The dependency was vendored here (as `fbs_runtime`) so that:

- zarrow has **zero external dependencies** — no network fetch required to build.
- The runtime can be maintained independently alongside the rest of zarrow,
  including forward-porting to new Zig versions without waiting on upstream.

## What is included

Only the runtime subset required by the pre-generated Arrow IPC schema code in
`src/ipc_schema/` is kept.  Each generated file references this module via
`@import("fbs_runtime")`.  Code-generation helpers (`codegen`, `idl`,
`reflection`, `binary_tools`) are intentionally omitted.

| File | Purpose |
|---|---|
| `lib.zig` | Module entry point — re-exports all public symbols |
| `Builder.zig` | FlatBuffers encoder (write path) |
| `Table.zig` | FlatBuffers table decoder (read path) |
| `encode.zig` | Low-level little-endian byte read/write helpers |
| `common.zig` | Shared types: `PackOptions`, `PackError`, `BuilderError` |
| `flatbuffers.zig` | Top-level helpers: `GetRootAs`, `BufferHasIdentifier`, etc. |

## Updating

If a bug fix or Zig compatibility patch is needed, edit the files in this
directory directly.  When pulling in changes from upstream flatbufferz, apply
the diff only to the files listed above and verify with `zig build test`.

The module is wired up in `build.zig` as a local module named `fbs_runtime`
(replacing the former `flatbufferz` external dependency).

