        error.RowCountMismatch,
        error.SchemaEndiannessMismatch,
        error.SchemaFieldMismatch,
        error.InvalidArgument,
        error.LayoutMismatch,
        => ZARROW_C_STATUS_INVALID_DATA,
        else => ZARROW_C_STATUS_INTERNAL,
    };
}

