    pub fn resize(self: *Self, newSize: usize) !void {
        const old_len = self.data.len;
        // After `toShared`/`deinit` there is no allocation (and no header slot) to grow.
        if (old_len == 0) {
            self.* = try init(self.allocator, newSize);
            return;
        }
