    try ids_builder.append(20);
    try ids_builder.append(30);
    var ids = try ids_builder.finish();
    defer ids.release();
    var names_builder = try @import("../array/string_array.zig").StringBuilder.init(allocator, 3, 6);
    defer names_builder.deinit();
