import json, sys, pathlib, collections
out = pathlib.Path(sys.argv[1])
groups = collections.defaultdict(list)


def cls(kind, msg, frames):
    fs = ' '.join(f'{f[2]}@{f[0]}' for f in frames)
    if 'fbs_runtime' in fs or 'ipc_schema' in fs:
        return 'R1 unverified flatbuffer (offset/enum/overflow/oom in generated unpack)'
    if kind == 'oom' and ('readMessageOptional' in fs or 'reuseOrAlloc' in fs):
        return 'R2 length prefix sizes allocation'
    if kind == 'leak' and 'readArrayFromMeta' in fs:
        return 'R3 readArrayFromMeta children leak'
    if kind == 'leak' and ('skipPadding' in fs or 'readMessageOptional' in fs):
        return 'R4 readMessageOptional body leak'
    if 'buildRecordBatchFromFlatbuf' in fs and ('Segmentation' in msg or 'release' in fs):
        return 'R5 buildRecordBatchFromFlatbuf double release'
    if 'concat' in fs and 'slice' in fs:
        return 'R6 nested child bound uses child.offset+length (concat slices past child)'
    if 'validateLayout' in fs and 'index out of bounds' in msg:
        return 'R7 REE run-ends window unchecked'
    if 'extension' in msg:
        return 'R8 ArrayRef.slice of extension<struct>'
    return 'OTHER ' + kind + ' ' + msg[:80] + ' ' + fs[:200]


for idx in sorted(out.glob('*/index.json')):
    t = idx.parent.name
    for sig, e in json.loads(idx.read_text()).items():
        c = cls(e['kind'], e['message'], e.get('frames') or [])
        groups[c].append((t, e['count'], e['size'], idx.parent / (e['smallest'] + '.bin'), sig))
