1	//! zarrow fuzz harness: one executable, one `runOne` per target (see docs/fuzzing.md).
2	//!
3	//!   zarrow-fuzz <target> replay <file|dir>...
4	//!   zarrow-fuzz <target> run <N|Ns> --corpus <dir>... --out <dir> [--seed N] [--max-len N]
5	//!   zarrow-fuzz gen-seeds <corpus-root>
6	//!
7	//! Every decoded array goes through validateFull. A returned error is a pass; a panic, hang,
8	//! leak or allocation over the cap is a finding. The same `runOne` backs the std.testing.fuzz
9	//! tests at the bottom (`zig build fuzz-test --fuzz=100K`, Linux only).
10	const std = @import("std");
11	const zarrow = @import("zarrow");
12	
13	const Allocator = std.mem.Allocator;
14	const ArrayRef = zarrow.ArrayRef;
15	const DataType = zarrow.DataType;
16	const Field = zarrow.Field;
17	
18	pub const Target = enum {
19	    @"ipc-stream",
20	    @"ipc-stream-zero-copy",
21	    @"ipc-file",
22	    @"array-layout",
23	    compute,
24	    @"c-abi",
25	};
26	
27	/// Inputs over this size are skipped (replay) or never produced (run).
28	pub const max_input_len: usize = 1 << 20;
29	/// Live bytes one input may allocate before it counts as an OOM finding.
30	pub var alloc_cap: usize = 256 << 20;
31	/// Print the error return trace of a rejected input (set by single-file replay).
32	var explain = false;
33	const max_batches = 64;
34	
35	/// What one execution looked like; a new `sig` grows the corpus (our stand-in for coverage).
36	pub const Feedback = struct {
37	    err: ?anyerror = null,
38	    batches: u32 = 0,
39	    types: u64 = 0, // bit per decoded TypeId (mod 64), children included
40	    invalid: ?anyerror = null, // first validateFull error
41	
42	    fn sig(f: Feedback) u64 {
43	        var h = std.hash.Wyhash.init(0);
44	        h.update(if (f.err) |e| @errorName(e) else "ok");
45	        h.update(if (f.invalid) |e| @errorName(e) else "valid");
46	        h.update(std.mem.asBytes(&@min(f.batches, 8)));
47	        h.update(std.mem.asBytes(&f.types));
48	        return h.final();
49	    }
50	
51	    fn typeBits(data: *const zarrow.ArrayData) u64 {
52	        var bits = @as(u64, 1) << @intCast(@intFromEnum(data.data_type.id()) % 64);
53	        for (data.children) |child| bits |= typeBits(child.data());
54	        return bits;
55	    }
56	
57	    fn noteArray(f: *Feedback, arr: ArrayRef) bool {
58	        f.types |= typeBits(arr.data());
59	        arr.data().validateFull() catch |e| {
60	            if (f.invalid == null) f.invalid = e;
61	            return false;
62	        };
63	        return true;
64	    }
65	};
66	
67	// ---------------------------------------------------------------------------------------------
68	// Allocation cap + per-input leak check.
69	
70	const CountingAllocator = struct {
71	    parent: Allocator,
72	    live: usize = 0,
73	
74	    fn allocator(self: *CountingAllocator) Allocator {
75	        return .{ .ptr = self, .vtable = &.{ .alloc = alloc, .resize = resize, .remap = remap, .free = free } };
76	    }
77	
78	    fn charge(self: *CountingAllocator, old: usize, new: usize) void {
79	        if (new > old and self.live + (new - old) > alloc_cap)
80	            std.debug.panic("fuzz-oom: allocation of {d} bytes with {d} live exceeds cap {d}", .{ new - old, self.live, alloc_cap });
81	    }
82	
83	    fn alloc(ctx: *anyopaque, len: usize, a: std.mem.Alignment, ra: usize) ?[*]u8 {
84	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
85	        self.charge(0, len);
86	        const p = self.parent.rawAlloc(len, a, ra) orelse return null;
87	        self.live += len;
88	        return p;
89	    }
90	
91	    fn resize(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) bool {
92	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
93	        self.charge(m.len, n);
94	        if (!self.parent.rawResize(m, a, n, ra)) return false;
95	        self.live = self.live - m.len + n;
96	        return true;
97	    }
