99	    fn remap(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) ?[*]u8 {
100	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
101	        self.charge(m.len, n);
102	        const p = self.parent.rawRemap(m, a, n, ra) orelse return null;
103	        self.live = self.live - m.len + n;
104	        return p;
105	    }
106	
107	    fn free(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, ra: usize) void {
108	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
109	        self.parent.rawFree(m, a, ra);
110	        self.live -= m.len;
111	    }
112	};
