114	/// Runs one input against `target`. Panics (= finding) on leaks, cap overruns and broken
115	/// invariants; library errors are returned in the feedback.
116	pub fn runOne(target: Target, parent: Allocator, bytes: []const u8) Feedback {
117	    var counting: CountingAllocator = .{ .parent = parent };
118	    const gpa = counting.allocator();
119	    var fb: Feedback = .{};
120	    const result = switch (target) {
121	        .@"ipc-stream" => ipcStream(gpa, bytes, false, &fb),
122	        .@"ipc-stream-zero-copy" => ipcStream(gpa, bytes, true, &fb),
123	        .@"ipc-file" => ipcFile(gpa, bytes, &fb),
124	        .compute => computeTarget(gpa, bytes, &fb),
125	        .@"array-layout" => arrayLayout(gpa, bytes, &fb),
126	        .@"c-abi" => cAbi(gpa, bytes, &fb),
127	    };
128	    result catch |e| {
129	        fb.err = e;
130	        // Single-file replay: show where the input was rejected (compat-gap triage).
131	        if (explain) if (@errorReturnTrace()) |trace| std.debug.dumpErrorReturnTrace(trace);
132	    };
133	    if (counting.live != 0) std.debug.panic("fuzz-leak: {d} bytes still allocated after the input", .{counting.live});
134	    return fb;
135	}
136	
137	// ---------------------------------------------------------------------------------------------
138	// IPC targets.
139	
140	fn noteBatch(fb: *Feedback, batch: *const zarrow.RecordBatch) void {
141	    fb.batches += 1;
142	    for (0..batch.numColumns()) |i| _ = fb.noteArray(batch.column(i).*);
143	}
144	
145	fn ipcStream(gpa: Allocator, bytes: []const u8, zero_copy: bool, fb: *Feedback) !void {
146	    const zc = zero_copy and bytes.len > 0;
147	    var source = zarrow.SharedBuffer.empty;
148	    if (zc) {
149	        var owned = try zarrow.OwnedBuffer.initUninit(gpa, bytes.len);
150	        @memcpy(owned.data[0..bytes.len], bytes);
151	        source = try owned.toShared(bytes.len);
152	    }
153	    defer source.release();
154	    var fixed: std.Io.Reader = .fixed(if (zc) source.data else bytes);
155	    var reader = if (zc) zarrow.IpcStreamReader.initZeroCopy(gpa, &fixed, source) else zarrow.IpcStreamReader.init(gpa, &fixed);
156	    defer reader.deinit();
157	
158	    _ = reader.readSchema() catch |e| {
159	        // Tensor streams have no schema message: walk them with the tensor API instead.
160	        var fixed2: std.Io.Reader = .fixed(bytes);
161	        var tensors = zarrow.IpcStreamReader.init(gpa, &fixed2);
162	        defer tensors.deinit();
163	        while (fb.batches < max_batches) {
164	            var msg = (tensors.nextTensorLikeMessage() catch break) orelse break;
165	            msg.deinit();
166	            fb.batches += 1;
167	        }
168	        return e;
169	    };
170	    while (fb.batches < max_batches) {
171	        var batch = (try reader.nextRecordBatch()) orelse return;
172	        defer batch.deinit();
173	        noteBatch(fb, &batch);
174	    }
175	}
176	
177	fn ipcFile(gpa: Allocator, bytes: []const u8, fb: *Feedback) !void {
178	    var reader = zarrow.IpcFileReader.init(gpa, bytes);
179	    defer reader.deinit();
180	    _ = try reader.readSchema();
181	    const n = try reader.recordBatchCount();
182	    for (0..@min(n, max_batches)) |i| {
183	        var batch = try reader.readRecordBatchAt(i);
184	        defer batch.deinit();
185	        noteBatch(fb, &batch);
186	    }
187	    for (0..@min(try reader.tensorCount(), max_batches)) |i| {
188	        var t = try reader.readTensorAt(i);
189	        t.deinit();
190	    }
191	    for (0..@min(try reader.sparseTensorCount(), max_batches)) |i| {
192	        var t = try reader.readSparseTensorAt(i);
193	        t.deinit();
194	    }
195	}
196	
197	fn computeTarget(gpa: Allocator, bytes: []const u8, fb: *Feedback) !void {
198	    var prng = std.Random.DefaultPrng.init(std.hash.Wyhash.hash(1, bytes));
199	    var fixed: std.Io.Reader = .fixed(bytes);
200	    var reader = zarrow.IpcStreamReader.init(gpa, &fixed);
201	    defer reader.deinit();
202	    _ = try reader.readSchema();
203	    while (fb.batches < max_batches) {
204	        var batch = (try reader.nextRecordBatch()) orelse return;
205	        defer batch.deinit();
206	        fb.batches += 1;
207	        for (0..batch.numColumns()) |i| {
208	            const col = batch.column(i).*;
209	            if (fb.noteArray(col)) try exerciseCompute(gpa, col, prng.random());
210	        }
211	    }
212	}
213	
214	/// slice/take/filter/concat on an array that passed validateFull; every output must validate
215	/// and have the expected length, otherwise the kernel broke an invariant (a finding).
216	fn exerciseCompute(gpa: Allocator, arr: ArrayRef, rng: std.Random) !void {
217	    const len = arr.data().length;
218	    const off = rng.uintAtMost(usize, len);
219	    const sub_len = rng.uintAtMost(usize, len - off);
220	    var sliced = try arr.slice(off, sub_len);
221	    defer sliced.release();
222	    expectValid("slice", sliced, sub_len);
223	
224	    var indices: [32]usize = undefined;
225	    const n_idx = if (len == 0) 0 else rng.uintAtMost(usize, indices.len);
226	    for (indices[0..n_idx]) |*ix| ix.* = rng.uintLessThan(usize, len);
227	    if (zarrow.computeDatumTake(.{ .array = arr }, indices[0..n_idx])) |taken| {
228	        var out = taken;
229	        defer out.release();
230	        if (out.asArray()) |a| expectValid("take", a, n_idx);
231	    } else |_| {}
232	
233	    var pred_builder = try zarrow.BooleanBuilder.init(gpa, len);
234	    defer pred_builder.deinit();
235	    var expected_rows: usize = 0;
236	    const drop_nulls = rng.boolean();
237	    for (0..len) |_| switch (rng.uintLessThan(u8, 3)) {
238	        0 => try pred_builder.append(false),
239	        1 => {
240	            try pred_builder.append(true);
241	            expected_rows += 1;
242	        },
243	        else => {
244	            try pred_builder.appendNull();
245	            if (!drop_nulls) expected_rows += 1;
246	        },
247	    };
248	    var pred = try pred_builder.finish();
249	    defer pred.release();
250	    if (zarrow.computeDatumFilter(.{ .array = arr }, .{ .array = pred }, .{ .drop_nulls = drop_nulls })) |filtered| {
251	        var out = filtered;
252	        defer out.release();
253	        if (out.asArray()) |a| expectValid("filter", a, expected_rows);
254	    } else |_| {}
255	
256	    if (zarrow.concatArrayRefs(gpa, arr.data().data_type, &.{ arr, sliced })) |joined| {
257	        var out = joined;
258	        defer out.release();
259	        expectValid("concat", out, len + sub_len);
260	    } else |_| {}
261	}
262	
263	fn expectValid(op: []const u8, arr: ArrayRef, expected_len: usize) void {
264	    arr.data().validateFull() catch |e| std.debug.panic("fuzz-invariant: {s} of a valid {s} array failed validateFull: {s}", .{ op, @tagName(arr.data().data_type.id()), @errorName(e) });
265	    if (arr.data().length != expected_len)
266	        std.debug.panic("fuzz-invariant: {s} returned {d} rows, expected {d}", .{ op, arr.data().length, expected_len });
267	}
268	
269	// ---------------------------------------------------------------------------------------------
270	// array-layout: hand-built ArrayData from bytes (structure from the input, contents from a PRNG).
271	
272	const Input = struct {
273	    bytes: []const u8,
274	    pos: usize = 0,
275	
276	    fn byte(in: *Input) u8 {
277	        if (in.pos >= in.bytes.len) return 0;
278	        defer in.pos += 1;
279	        return in.bytes[in.pos];
280	    }

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

